import{_ as d,o as r,c as o,a2 as a}from"./chunks/framework.CRFziyHp.js";const b=JSON.parse('{"title":"基础元素组件","description":"","frontmatter":{"prev":{"text":"样式与点击动作","link":"/features/ui-editor/styles-and-actions"},"next":{"text":"布局导航组件","link":"/features/ui-editor/components-layout"}},"headers":[],"relativePath":"features/ui-editor/components-basic.md","filePath":"features/ui-editor/components-basic.md","lastUpdated":1785013113000}'),e={name:"features/ui-editor/components-basic.md"};function n(l,t,i,s,h,c){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="基础元素组件" tabindex="-1">基础元素组件 <a class="header-anchor" href="#基础元素组件" aria-label="Permalink to &quot;基础元素组件&quot;">​</a></h1><p>本篇介绍 UI 编辑器 <strong>基础元素</strong> 分类下的 4 个组件：<strong>文本</strong>、<strong>图片</strong>、<strong>按钮</strong>、<strong>模块标题</strong>。它们适合在首页、发现页、自定义页、圈子页中拼装文案、配图与操作入口。</p><div class="tip custom-block"><p class="custom-block-title">通用说明</p><p>除下文「属性」外，所有组件都可在右侧 <strong>样式</strong> Tab 调整宽高、内外边距、背景、圆角、边框等。点击跳转请在 <strong>点击动作</strong> 中配置，详见 <a href="/features/ui-editor/styles-and-actions">样式与点击动作</a>。</p></div><hr><h2 id="文本" tabindex="-1">文本 <a class="header-anchor" href="#文本" aria-label="Permalink to &quot;文本&quot;">​</a></h2><p><strong>组件说明：</strong> 在页面上展示一段可自定义样式的文字，支持多行与省略。</p><h3 id="适用页面" tabindex="-1">适用页面 <a class="header-anchor" href="#适用页面" aria-label="Permalink to &quot;适用页面&quot;">​</a></h3><table tabindex="0"><thead><tr><th>页面类型</th><th>是否可用</th></tr></thead><tbody><tr><td>应用首页、功能页面、自定义页面</td><td>✅</td></tr><tr><td>社区圈子</td><td>✅</td></tr><tr><td>服务表单</td><td>❌</td></tr></tbody></table><h3 id="如何添加" tabindex="-1">如何添加 <a class="header-anchor" href="#如何添加" aria-label="Permalink to &quot;如何添加&quot;">​</a></h3><ol><li>进入 <strong>UI管理 → 页面配置</strong>，打开目标页面的 <strong>设计</strong> 界面</li><li>左侧组件库展开 <strong>基础元素</strong></li><li>点击 <strong>文本</strong>，组件会插入画布并自动选中</li><li>在右侧 <strong>属性</strong> Tab 填写内容与文字样式；<strong>样式</strong> Tab 调整边距与背景</li></ol><h3 id="属性配置" tabindex="-1">属性配置 <a class="header-anchor" href="#属性配置" aria-label="Permalink to &quot;属性配置&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性名</th><th>说明</th><th>常用值/示例</th></tr></thead><tbody><tr><td>文本内容</td><td>页面上显示的文字，支持换行</td><td><code>欢迎来到灵萌</code>、<code>活动规则说明…</code></td></tr><tr><td>字号</td><td>文字大小，单位 rpx</td><td><code>28</code>（正文）、<code>32</code>（小标题）</td></tr><tr><td>颜色</td><td>文字颜色</td><td><code>#333333</code>、<code>#999999</code></td></tr><tr><td>字重</td><td>粗细</td><td>正常 / 中等 / 粗体</td></tr><tr><td>对齐</td><td>水平对齐</td><td>左 / 中 / 右</td></tr><tr><td>斜体 / 下划线 / 删除线</td><td>文字装饰，可多选</td><td>按需开启</td></tr><tr><td>行高</td><td>行间距倍数</td><td><code>1.4</code>、<code>1.6</code></td></tr><tr><td>最多行数</td><td>限制显示行数，超出配合省略</td><td>留空=不限；<code>2</code>（两行摘要）</td></tr><tr><td>超出省略</td><td>超出「最多行数」时显示省略号</td><td>开启</td></tr><tr><td>点击动作</td><td>用户点击文字时的跳转</td><td>跳转页面、打开链接等</td></tr></tbody></table><h3 id="样式建议" tabindex="-1">样式建议 <a class="header-anchor" href="#样式建议" aria-label="Permalink to &quot;样式建议&quot;">​</a></h3><ul><li>正文推荐字号 <strong>26～30</strong> rpx，标题可 <strong>32～36</strong> rpx</li><li>长说明配合 <strong>最多行数 + 超出省略</strong>，避免撑破布局</li><li>边距、背景色请在 <strong>样式</strong> Tab 设置，属性面板底部有提示</li></ul><h3 id="使用技巧-注意事项" tabindex="-1">使用技巧 / 注意事项 <a class="header-anchor" href="#使用技巧-注意事项" aria-label="Permalink to &quot;使用技巧 / 注意事项&quot;">​</a></h3><ul><li>需要整块留白时，优先用 <strong>样式 → 外边距</strong>，不必在文本里打空格</li><li>设置了 <strong>点击动作</strong> 后，文字区域可点击跳转</li><li>服务表单页不提供文本组件，说明类内容请用表单内的 <strong>表单说明</strong> 组件</li></ul><hr><h2 id="图片" tabindex="-1">图片 <a class="header-anchor" href="#图片" aria-label="Permalink to &quot;图片&quot;">​</a></h2><p><strong>组件说明：</strong> 展示单张图片，支持圆角、头像、预览、角标与遮罩。</p><h3 id="适用页面-1" tabindex="-1">适用页面 <a class="header-anchor" href="#适用页面-1" aria-label="Permalink to &quot;适用页面&quot;">​</a></h3><table tabindex="0"><thead><tr><th>页面类型</th><th>是否可用</th></tr></thead><tbody><tr><td>应用首页、功能页面、自定义页面</td><td>✅</td></tr><tr><td>社区圈子</td><td>✅</td></tr><tr><td>服务表单</td><td>❌（请用 <strong>图片上传</strong> 表单组件）</td></tr></tbody></table><h3 id="如何添加-1" tabindex="-1">如何添加 <a class="header-anchor" href="#如何添加-1" aria-label="Permalink to &quot;如何添加&quot;">​</a></h3><ol><li>左侧 <strong>基础元素 → 图片</strong></li><li>在 <strong>图片地址</strong> 处粘贴链接，或点 <strong>选择</strong> 从媒体库上传</li><li>在 <strong>样式</strong> Tab 设置宽度；高度留空时可按图片比例自适应</li></ol><h3 id="属性配置-1" tabindex="-1">属性配置 <a class="header-anchor" href="#属性配置-1" aria-label="Permalink to &quot;属性配置&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性名</th><th>说明</th><th>常用值/示例</th></tr></thead><tbody><tr><td>图片地址</td><td>图片 URL</td><td>媒体库选择或粘贴链接</td></tr><tr><td>显示模式</td><td>图片在框内的填充方式</td><td>裁剪填充 / 完整显示 / 宽度撑满 / 拉伸铺满</td></tr><tr><td>圆角</td><td>图片圆角，rpx</td><td><code>0</code>（直角）、<code>16</code>（卡片感）</td></tr><tr><td>圆形头像</td><td>裁成圆形，适合头像</td><td>开启；样式宽高建议相同</td></tr><tr><td>点击预览</td><td>点击放大查看</td><td>开启（未设跳转时生效）</td></tr><tr><td>懒加载</td><td>滚动到附近再加载</td><td>长页建议开启</td></tr><tr><td>渐显</td><td>加载完成后淡入</td><td>按需</td></tr><tr><td>启用遮罩</td><td>图片上叠加半透明层</td><td>活动 banner 可加文字层时使用</td></tr><tr><td>遮罩颜色 / 遮罩透明度</td><td>遮罩样式</td><td>黑色 + <code>0.4</code></td></tr><tr><td>角标文字</td><td>角上小标签</td><td><code>HOT</code>、<code>新</code></td></tr><tr><td>角标位置</td><td>角标所在角落</td><td>右上 / 左上 / 右下 / 左下</td></tr><tr><td>角标背景</td><td>角标底色</td><td>品牌色</td></tr><tr><td>点击动作</td><td>点击优先跳转，不再预览</td><td>活动页、商品详情等</td></tr><tr><td>加载中 / 失败占位 / 失败角标</td><td>加载与出错时的展示</td><td>网络图建议开启</td></tr><tr><td>失败文字</td><td>加载失败提示文案</td><td><code>加载失败</code></td></tr></tbody></table><h3 id="样式建议-1" tabindex="-1">样式建议 <a class="header-anchor" href="#样式建议-1" aria-label="Permalink to &quot;样式建议&quot;">​</a></h3><ul><li>Banner 类图片：样式 <strong>宽度</strong> 留空或 <code>750</code>，<strong>高度</strong> 设 <code>300～400</code> rpx</li><li>头像：<code>圆形头像</code> 开启，宽高各 <strong>80～120</strong> rpx</li><li>高度填 <strong>auto</strong> 时，会自动按宽度撑满模式适配比例</li></ul><h3 id="使用技巧-注意事项-1" tabindex="-1">使用技巧 / 注意事项 <a class="header-anchor" href="#使用技巧-注意事项-1" aria-label="Permalink to &quot;使用技巧 / 注意事项&quot;">​</a></h3><ul><li><strong>点击动作</strong> 与 <strong>点击预览</strong> 互斥：设了跳转就不再放大预览</li><li>大图建议压缩后上传，并开启 <strong>懒加载</strong></li><li>角标文字不宜过长，1～3 个字为宜</li></ul><hr><h2 id="按钮" tabindex="-1">按钮 <a class="header-anchor" href="#按钮" aria-label="Permalink to &quot;按钮&quot;">​</a></h2><p><strong>组件说明：</strong> 可点击的操作按钮，支持配色、图标与多种视觉状态。</p><h3 id="适用页面-2" tabindex="-1">适用页面 <a class="header-anchor" href="#适用页面-2" aria-label="Permalink to &quot;适用页面&quot;">​</a></h3><table tabindex="0"><thead><tr><th>页面类型</th><th>是否可用</th></tr></thead><tbody><tr><td>应用首页、功能页面、自定义页面</td><td>✅</td></tr><tr><td>社区圈子</td><td>✅</td></tr><tr><td>服务表单</td><td>❌（请用 <strong>提交按钮</strong> / <strong>提交底栏</strong>）</td></tr></tbody></table><h3 id="如何添加-2" tabindex="-1">如何添加 <a class="header-anchor" href="#如何添加-2" aria-label="Permalink to &quot;如何添加&quot;">​</a></h3><ol><li>左侧 <strong>基础元素 → 按钮</strong></li><li>填写 <strong>按钮文字</strong>，配置颜色与 <strong>点击动作</strong></li><li>在 <strong>样式</strong> Tab 设置宽度、高度、圆角、边框</li></ol><h3 id="属性配置-2" tabindex="-1">属性配置 <a class="header-anchor" href="#属性配置-2" aria-label="Permalink to &quot;属性配置&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性名</th><th>说明</th><th>常用值/示例</th></tr></thead><tbody><tr><td>按钮文字</td><td>按钮上显示的文字</td><td><code>立即参与</code>、<code>查看更多</code></td></tr><tr><td>字号</td><td>文字大小，rpx</td><td><code>26</code>～<code>30</code></td></tr><tr><td>字重</td><td>文字粗细</td><td>正常 / 中等 / 粗体</td></tr><tr><td>文字颜色</td><td>按钮文字色</td><td>白底按钮用 <code>#000000</code></td></tr><tr><td>背景颜色</td><td>按钮背景，可透明</td><td>黑底白字：<code>#000000</code> + 白字</td></tr><tr><td>边框颜色</td><td>描边按钮的边框色</td><td>白底黑边：<code>#000000</code></td></tr><tr><td>点击动作</td><td>点击后跳转或触发行为</td><td>必填，否则按钮无实际作用</td></tr><tr><td>图标名</td><td>按钮旁图标</td><td>点 <strong>选择</strong> 挑选；如加号、箭头</td></tr><tr><td>图标位置</td><td>图标在文字哪侧</td><td>左侧 / 右侧</td></tr><tr><td>图标大小</td><td>图标尺寸，rpx</td><td>留空随字号；<code>32</code></td></tr><tr><td>镂空</td><td>透明底、保留边框与文字</td><td>次要按钮</td></tr><tr><td>禁用预览</td><td>编辑器内预览禁用态</td><td>仅预览，不影响保存</td></tr><tr><td>加载预览</td><td>编辑器内预览加载态</td><td>仅预览</td></tr></tbody></table><h3 id="样式建议-2" tabindex="-1">样式建议 <a class="header-anchor" href="#样式建议-2" aria-label="Permalink to &quot;样式建议&quot;">​</a></h3><ul><li>主按钮：深色背景 + 白字 + 圆角 <strong>40～50</strong> rpx（胶囊形）</li><li>次要按钮：<strong>镂空</strong> + 细边框</li><li>全宽按钮：样式宽度留空，左右 <strong>margin</strong> 各 <code>24</code> rpx</li></ul><h3 id="使用技巧-注意事项-2" tabindex="-1">使用技巧 / 注意事项 <a class="header-anchor" href="#使用技巧-注意事项-2" aria-label="Permalink to &quot;使用技巧 / 注意事项&quot;">​</a></h3><ul><li>默认风格为 <strong>黑底白字</strong>；描边样式可设白底 + 黑边框</li><li>宽高、圆角、边框在 <strong>样式</strong> Tab，不在属性里</li><li><strong>禁用预览 / 加载预览</strong> 只影响编辑器展示，客户端以实际业务为准</li><li>务必配置 <strong>点击动作</strong>，否则用户点击无响应</li></ul><hr><h2 id="模块标题" tabindex="-1">模块标题 <a class="header-anchor" href="#模块标题" aria-label="Permalink to &quot;模块标题&quot;">​</a></h2><p><strong>组件说明：</strong> 带可选图标与「更多」入口的分区标题，用于划分首页模块。</p><h3 id="适用页面-3" tabindex="-1">适用页面 <a class="header-anchor" href="#适用页面-3" aria-label="Permalink to &quot;适用页面&quot;">​</a></h3><table tabindex="0"><thead><tr><th>页面类型</th><th>是否可用</th></tr></thead><tbody><tr><td>应用首页、功能页面、自定义页面</td><td>✅</td></tr><tr><td>社区圈子</td><td>✅</td></tr><tr><td>服务表单</td><td>❌</td></tr></tbody></table><h3 id="如何添加-3" tabindex="-1">如何添加 <a class="header-anchor" href="#如何添加-3" aria-label="Permalink to &quot;如何添加&quot;">​</a></h3><ol><li>左侧 <strong>基础元素 → 模块标题</strong></li><li>填写 <strong>标题文本</strong>，按需加左侧图标与 <strong>更多</strong></li><li>放在轮播、列表等模块上方，形成清晰分区</li></ol><h3 id="属性配置-3" tabindex="-1">属性配置 <a class="header-anchor" href="#属性配置-3" aria-label="Permalink to &quot;属性配置&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性名</th><th>说明</th><th>常用值/示例</th></tr></thead><tbody><tr><td>标题文本</td><td>模块名称</td><td><code>热门圈子</code>、<code>最新动态</code></td></tr><tr><td>字号</td><td>标题大小，rpx</td><td><code>40</code>（默认）、<code>36</code>（紧凑）</td></tr><tr><td>文字颜色</td><td>标题颜色</td><td><code>#000000</code></td></tr><tr><td>字重</td><td>标题粗细</td><td>粗体</td></tr><tr><td>对齐</td><td>标题对齐</td><td>左 / 中 / 右</td></tr><tr><td>图标名</td><td>标题左侧字体图标</td><td>点 <strong>选择</strong>；如 star、fire</td></tr><tr><td>或图片</td><td>标题左侧图片，优先于图标名</td><td>品牌小 logo</td></tr><tr><td>图标大小</td><td>图标或图片边长，rpx</td><td><code>40</code></td></tr><tr><td>图片圆角</td><td>仅图片模式生效</td><td><code>8</code></td></tr><tr><td>与标题间距</td><td>图标与标题距离，rpx</td><td><code>12</code></td></tr><tr><td>显示更多</td><td>右侧是否显示「更多」</td><td>有列表详情页时开启</td></tr><tr><td>更多文案</td><td>右侧文字</td><td><code>更多</code>、<code>查看全部</code></td></tr><tr><td>更多颜色 / 字号</td><td>「更多」样式</td><td>浅灰 <code>#999</code>、字号 <code>24</code></td></tr><tr><td>更多点击动作</td><td>点击「更多」的跳转</td><td>列表页、专题页等</td></tr></tbody></table><h3 id="样式建议-3" tabindex="-1">样式建议 <a class="header-anchor" href="#样式建议-3" aria-label="Permalink to &quot;样式建议&quot;">​</a></h3><ul><li>标题与下方内容之间：样式 <strong>marginBottom</strong> <code>16～24</code> rpx</li><li>长首页每个运营区块前放一条模块标题，层次更清晰</li><li>左对齐 + 左侧小图标，是常见首页排版</li></ul><h3 id="使用技巧-注意事项-3" tabindex="-1">使用技巧 / 注意事项 <a class="header-anchor" href="#使用技巧-注意事项-3" aria-label="Permalink to &quot;使用技巧 / 注意事项&quot;">​</a></h3><ul><li><strong>对齐设为居中</strong> 时，右侧 <strong>更多</strong> 不会显示</li><li>若同时填了 <strong>图标名</strong> 和 <strong>图片</strong>，<strong>图片优先</strong></li><li>边距、背景请在 <strong>样式</strong> Tab 配置</li><li>常与 <strong>笔记列表</strong>、<strong>热门圈子</strong> 等组合：标题在上，内容组件在下</li></ul><hr><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>继续阅读 <a href="/features/ui-editor/components-layout">布局导航组件</a> — 轮播图、金刚区、搜索栏、筛选标签等。</p>',58)])])}const u=d(e,[["render",n]]);export{b as __pageData,u as default};
